"""Conversation-lane retirement decision matrix x contention programs grid.

Generated by the emit-time cross-verified emitter (see
tests/unit/quiet_retirement_grid_harness.py): every cell ran the real
retirement boundary and agreed with the hand-transcribed model before
its literals were frozen. One facet per test.

Failure-Class: FC-quiet-retirement-defers-a-replayable-abort-to-the-durable-backstop
"""

import pytest

from tests.unit.quiet_retirement_grid_harness import run_conv_cell


def test_conv_waiting_missing_clean_outcome():
    cell = run_conv_cell('quiet', 'waiting', 'missing', 'clean')
    assert cell['result'] is True


def test_conv_waiting_missing_clean_job_state():
    cell = run_conv_cell('quiet', 'waiting', 'missing', 'clean')
    assert cell['job_status_after'] == 'quiet_done'


def test_conv_waiting_missing_clean_attempts():
    cell = run_conv_cell('quiet', 'waiting', 'missing', 'clean')
    assert cell['transactions'] == 1
    assert cell['outer_sleeps'] == pytest.approx([])
    assert cell['inner_sleeps'] == pytest.approx([])


def test_conv_waiting_missing_clean_defer():
    cell = run_conv_cell('quiet', 'waiting', 'missing', 'clean')
    assert cell['deferred'] is False


def test_conv_waiting_missing_clean_writes():
    cell = run_conv_cell('quiet', 'waiting', 'missing', 'clean')
    assert cell['writes'] == 1


